revoke all on all tables in schema public from anon,authenticated; grant select on public.tours,public.teams,public.tour_players,public.rounds,public.round_course_snapshots,public.round_hole_snapshots,public.round_players,public.matches,public.match_participants,public.match_handicaps,public.hole_scores,public.team_hole_scores,public.selected_drives,public.alternate_shot_settings,public.match_confirmations to authenticated; grant select on public.courses,public.course_tees,public.course_holes to authenticated; grant select on public.tours,public.teams,public.tour_players,public.rounds to anon; grant insert,update,delete on public.tours,public.teams,public.tour_players,public.rounds,public.round_course_snapshots,public.round_hole_snapshots,public.round_players,public.matches,public.match_participants,public.match_handicaps,public.hole_scores,public.team_hole_scores,public.selected_drives,public.alternate_shot_settings,public.match_confirmations,public.invitations to authenticated; grant select on public.invitations,public.audit_log to authenticated; grant select,update on public.profiles to authenticated;
create or replace function public.validate_tour_player_team() returns trigger language plpgsql set search_path=public as $$ begin if not exists(select 1 from public.teams t where t.id=new.team_id and t.tour_id=new.tour_id) then raise exception 'Tour player team must belong to same tour'; end if; return new; end;$$; create trigger validate_tour_player_team_before before insert or update on public.tour_players for each row execute function public.validate_tour_player_team();
create or replace function public.validate_round_tee() returns trigger language plpgsql set search_path=public as $$ begin if not exists(select 1 from public.course_tees ct where ct.id=new.course_tee_id and ct.course_id=new.course_id) then raise exception 'Round tee must belong to selected course'; end if; return new; end;$$; create trigger validate_round_tee_before before insert or update on public.rounds for each row execute function public.validate_round_tee();
create or replace function public.validate_match_participant_scope() returns trigger language plpgsql set search_path=public as $$ declare match_tour_id uuid;player_tour_id uuid;player_team_id uuid; begin select r.tour_id into match_tour_id from public.matches m join public.rounds r on r.id=m.round_id where m.id=new.match_id; select tp.tour_id,tp.team_id into player_tour_id,player_team_id from public.tour_players tp where tp.id=new.tour_player_id; if match_tour_id is distinct from player_tour_id then raise exception 'Participant must belong to match tour'; end if; if player_team_id is distinct from new.team_id then raise exception 'Participant team mismatch'; end if; return new; end;$$; create trigger validate_match_participant_scope_before before insert or update on public.match_participants for each row execute function public.validate_match_participant_scope();
create or replace function public.validate_individual_score_scope() returns trigger language plpgsql set search_path=public as $$ declare actual_round uuid; begin select m.round_id into actual_round from public.matches m where m.id=new.match_id; if actual_round is distinct from new.round_id then raise exception 'Score round does not match match round'; end if; if not exists(select 1 from public.match_participants mp where mp.match_id=new.match_id and mp.tour_player_id=new.tour_player_id) then raise exception 'Golfer is not a participant in this match'; end if; return new; end;$$; create trigger validate_individual_score_scope_before before insert or update on public.hole_scores for each row execute function public.validate_individual_score_scope();
create or replace function public.reject_score_write_if_confirmed() returns trigger language plpgsql set search_path=public as $$ begin if exists(select 1 from public.match_confirmations mc where mc.match_id=coalesce(new.match_id,old.match_id) and mc.reopened_at is null) then raise exception 'Confirmed match must be reopened before editing scores'; end if; return coalesce(new,old); end;$$; create trigger reject_confirmed_individual_score before insert or update or delete on public.hole_scores for each row execute function public.reject_score_write_if_confirmed(); create trigger reject_confirmed_team_score before insert or update or delete on public.team_hole_scores for each row execute function public.reject_score_write_if_confirmed();
create or replace function public.protect_final_round_snapshot() returns trigger language plpgsql set search_path=public as $$ declare round_state public.round_status; begin select status into round_state from public.rounds where id=coalesce(new.round_id,old.round_id); if round_state in ('completed','void') then raise exception 'Final round snapshots are immutable'; end if; return coalesce(new,old); end;$$; create trigger protect_round_course_snapshot before update or delete on public.round_course_snapshots for each row execute function public.protect_final_round_snapshot(); create trigger protect_round_hole_snapshot before update or delete on public.round_hole_snapshots for each row execute function public.protect_final_round_snapshot();
create unique index invitations_one_pending_per_player on public.invitations(tour_player_id) where status='pending'; alter table public.invitations add constraint invitation_hash_minimum_length check(length(token_hash)>=43);
